def calculate(num1, operation, num2):
    """Return the result of applying operation to num1 and num2."""
    if operation == "+":
        return num1 + num2
    elif operation == "-":
        return num1 - num2
    elif operation == "*":
        return num1 * num2
    else:
        return num1 / num2

def process_text(text, uppercase=False, reverse=False):
    """Return the text with the requested transformations applied."""
    def to_uppercase(value):
        return value.upper()

    def reverse_text(value):
        return value[::-1]

    result = text
    if uppercase:
        result = to_uppercase(result)
    if reverse:
        result = reverse_text(result)
    return result
